INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q215262', 'Vedic period', 'The Vedic period, or the Vedic age (c. 1500 – c. 500 BCE), is the period in the late Bronze Age and early Iron Age of the history of India when the Vedic literature, including the Vedas (c. 1500–900 BCE), was composed in the northern Indian subcontinent, between the end of the urban Indus Valley Civilisation and a second urbanisation, which began in the central Indo-Gangetic Plain c. 600 BCE. The Vedas are liturgical texts which formed the basis of the influential Brahmanical ideology, which developed in the Kuru kingdom, a tribal union of several Indo-Aryan tribes. The Vedas contain…', -1500, NULL, NULL, -500, NULL, NULL, 'century', '15th century BCE – 5th century BCE', 79, 'https://en.wikipedia.org/wiki/Vedic_period'),
  ('Q4087480', 'Battle of Chaul', 'The Battle of Chaul was a naval battle between the Portuguese and the Egyptian Mamluk fleets in 1508 in the harbour of Chaul in India. The battle ended in a Mamluk victory.', 1508, 3, NULL, NULL, NULL, NULL, 'month', 'March 1508', 53, 'https://en.wikipedia.org/wiki/Battle_of_Chaul'),
  ('Q605321', 'Battle of Panipat', 'The First Battle of Panipat, on 21 April 1526 was fought between the invading forces of Babur against Ibrahim Khan Lodi, the Sultan of Delhi, in North India. Babur''s forces, employing gunpowder firearms and cannons, defeated Ibrahim.', 1526, 5, 1, NULL, NULL, NULL, 'day', '1 May 1526', 73, 'https://en.wikipedia.org/wiki/First_Battle_of_Panipat'),
  ('Q4166578', 'Battle of Khanwa', 'The Battle of Khanwa was fought at Khanwa in modern-day Rajasthan on 16 March 1527, between the Mughal Empire, led by Babur, and the Kingdom of Mewar, led by Rana Sanga for supremacy of Northern India. The battle ended in a Mughal victory and was a major event in medieval Indian history.', 1527, NULL, NULL, NULL, NULL, NULL, 'year', '1527', 55, 'https://en.wikipedia.org/wiki/Battle_of_Khanwa'),
  ('Q233414', 'Battle of Panipat', 'The Second Battle of Panipat was fought on 5 November 1556, between the Mughals under Akbar and king Hemu, titularly known as Hemchandra Vikramaditya. Hemchandra had conquered Delhi and Agra a few weeks earlier by defeating Mughal forces under Tardi Beg Khan in the Battle of Delhi.', 1556, 11, 5, NULL, NULL, NULL, 'day', '5 November 1556', 67, 'https://en.wikipedia.org/wiki/Second_Battle_of_Panipat'),
  ('Q1362188', 'Battle of Talikota', 'The Battle of Talikota, also known as that of Rakshasi-Tangadi, (23 January 1565) was a watershed battle fought between the Vijayanagara Empire and an alliance of the Deccan sultanates. The battle resulted in the defeat of Aliya Rama Raya which led to the eventual collapse of the polity and reconfigured Deccan politics.', 1565, 1, 26, NULL, NULL, NULL, 'day', '26 January 1565', 61, 'https://en.wikipedia.org/wiki/Battle_of_Talikota'),
  ('Q6957844', 'Nadir Shah''s invasion of India', 'In May 1738, Nader Shah of Iran, the founder of the Afsharid dynasty, invaded Northern India, eventually sacking Delhi in March 1739. His army easily defeated the crumbling Mughals at the Battle of Karnal and then occupied the Mughal capital.', 1738, 5, 10, 1740, NULL, NULL, 'day', '10 May 1738 – 1740', 57, 'https://en.wikipedia.org/wiki/Nader_Shah''s_invasion_of_India'),
  ('Q2736986', 'Battle of Karnal', 'The Battle of Karnal (Persian: نبرد کرنال) (24 February 1739) was a decisive victory for Nader Shah, the founder of the Afsharid dynasty of Iran, during his invasion of India. Nader''s forces defeated the army of Mughal emperor Muhammad Shah within three hours, paving the way for the Iranian sack of Delhi.', 1739, 2, 24, NULL, NULL, NULL, 'day', '24 February 1739', 58, 'https://en.wikipedia.org/wiki/Battle_of_Karnal'),
  ('Q1202492', 'Black Hole of Calcutta', 'The Black Hole of Calcutta was a dungeon in Fort William, Calcutta, measuring 14 by 18 feet (4.3 m × 5.5 m), in which troops of Siraj-ud-Daulah, the Nawab of Bengal, held British prisoners of war on the night of 20 June 1756. John Zephaniah Holwell, one of the British prisoners and an employee of the East India Company said that, after the fall of Fort William, the surviving British soldiers, Indian sepoys, and Indian civilians were imprisoned overnight in conditions so cramped that many people died from suffocation and heat exhaustion, and that 123 of 146 prisoners of war imprisoned there…', 1756, 6, 20, NULL, NULL, NULL, 'day', '20 June 1756', 62, 'https://en.wikipedia.org/wiki/Black_Hole_of_Calcutta'),
  ('Q203233', 'Battle of Plassey', 'The Battle of Plassey was a decisive victory of the British East India Company, under the leadership of Robert Clive, over the Nawab of Bengal and his French allies on 23 June 1757. The victory was made possible by the betrayal of Mir Jafar, Nawab Siraj-ud-Daulah''s commander in chief, as well as much of the Bengal Subah''s armies being earlier committed against an Afghan invasion led by Ahmad Shah Durrani against the Mughal Empire.', 1757, 6, 23, NULL, NULL, NULL, 'day', '23 June 1757', 77, 'https://en.wikipedia.org/wiki/Battle_of_Plassey'),
  ('Q658845', 'Battle of Wandiwash', 'The Battle of Wandiwash was a battle in India between the French and the British in 1760. The battle was part of the Third Carnatic War fought between the French and British colonial empires, which itself was a part of the global Seven Years'' War.', 1760, 1, 22, NULL, NULL, NULL, 'day', '22 January 1760', 53, 'https://en.wikipedia.org/wiki/Battle_of_Wandiwash'),
  ('Q1259218', 'Third Battle of Panipat', 'The Third Battle of Panipat took place on 14 January 1761 between the Maratha Empire and the invading army of the Durrani Empire. The battle took place in and around the city of Panipat, approximately 97 kilometres (60 mi) north of Delhi.', 1761, 1, 14, NULL, NULL, NULL, 'day', '14 January 1761', 70, 'https://en.wikipedia.org/wiki/Third_Battle_of_Panipat'),
  ('Q617070', 'First Anglo-Mysore War', 'The First Anglo-Mysore War (1767–1769) was a conflict in India between the Kingdom of Mysore and the East India Company. The war was instigated in part by the machinations of Asaf Jah II, the Nizam of Hyderabad, who sought to divert the company''s resources from attempts to gain control over the Northern Circars.', 1767, NULL, NULL, 1769, NULL, NULL, 'year', '1767–1769', 59, 'https://en.wikipedia.org/wiki/First_Anglo-Mysore_War'),
  ('Q1362209', 'First Anglo-Maratha War', 'The First Anglo-Maratha War (1775–1782) was the first conflict fought between the British East India Company and Maratha Empire in India. The war, fought in between Surat and Poona, began with the 1775 Treaty of Surat after the East India Company agreed to support the recently deposed Raghunathrao''s claim as Peshwa of the Maratha Empire.', 1775, NULL, NULL, 1782, NULL, NULL, 'year', '1775–1782', 64, 'https://en.wikipedia.org/wiki/First_Anglo-Maratha_War'),
  ('Q815204', 'Siege of Seringapatam', 'The siege of Seringapatam (5 April – 4 May 1799) was the final confrontation of the Fourth Anglo-Mysore War between the British East India Company and the Kingdom of Mysore led by Tipu Sultan who ruled after the death of his father. The British, with the allied Nizam Ali Khan, 2nd Nizam of Hyderabad and Maratha Empire, achieved a decisive victory after breaching the walls of the fortress at Seringapatam and storming the citadel.', 1799, NULL, NULL, 1799, 5, 4, 'year', '1799', 53, 'https://en.wikipedia.org/wiki/Siege_of_Seringapatam_(1799)'),
  ('Q129864', 'Indian Mutiny of 1857', 'The Indian Rebellion of 1857 was a major uprising in India in 1857–58 against the rule of the British East India Company, which functioned as a sovereign power on behalf of the British Crown. The rebellion began on 10 May 1857 as a mutiny of sepoys of the company''s garrison in Meerut, a town 40 miles (64 km) northeast of Delhi.', 1857, NULL, NULL, 1858, 6, 20, 'year', '1857 – 20 June 1858', 83, 'https://en.wikipedia.org/wiki/Indian_Rebellion_of_1857'),
  ('Q12427290', 'Chauri Chaura incident', 'The Chauri Chaura Incident took place on 4 February 1922 at Chauri Chaura in the Gorakhpur district of United Provinces (now Uttar Pradesh) in British India. The police fired upon a large group of protesters participating in the non-cooperation movement.', 1922, 2, 5, NULL, NULL, NULL, 'day', '5 February 1922', 57, 'https://en.wikipedia.org/wiki/Chauri_Chaura_incident'),
  ('Q3492593', '1934 Bihar earthquake', 'The 1934 Nepal–India earthquake or 1934 Bihar–Nepal earthquake was one of the worst earthquakes in India''s history. The towns of Munger and Muzaffarpur were completely destroyed.', 1934, 1, 15, NULL, NULL, NULL, 'day', '15 January 1934', 58, 'https://en.wikipedia.org/wiki/1934_Nepal%E2%80%93India_earthquake'),
  ('Q383614', 'Battle of Kohima', 'The Battle of Kohima was the turning point of the Japanese U-Go offensive into British India in 1944 during the Second World War. It took place in three stages from 4 April to 22 June 1944 around the town of Kohima, now the capital city of the state of Nagaland in Northeast India.', 1944, NULL, NULL, 1944, 6, 22, 'year', '1944', 66, 'https://en.wikipedia.org/wiki/Battle_of_Kohima'),
  ('Q707238', 'Battle of Imphal', 'The Battle of Imphal (Meitei: Japan Laan, lit. ''Japanese invasion''), also known as the "Stalingrad of the East" in combination with Kohima, took place in the region around the city of Imphal, the capital of the state of Manipur in Northeast India from March until July 1944. Japanese armies attempted to destroy the Allied forces at Imphal and invade India, but were driven back into Burma with heavy losses.', 1944, 3, 8, 1944, 7, 3, 'day', '8 March 1944 – 3 July 1944', 64, 'https://en.wikipedia.org/wiki/Battle_of_Imphal'),
  ('Q2096814', 'Direct Action Day', 'Direct Action Day (16 August 1946) was the day the All-India Muslim League decided to take a "direct action" using general strikes and economic shut down to demand a separate Muslim homeland after the British exit from India. Also known as the 1946 Calcutta Riots and Great Calcutta Killings, it soon became a day of communal violence in Calcutta.', 1946, 8, 16, NULL, NULL, NULL, 'day', '16 August 1946', 57, 'https://en.wikipedia.org/wiki/Direct_Action_Day'),
  ('Q1413732', 'Kashmir conflict', 'The Kashmir conflict is a territorial conflict over the Kashmir region, primarily between India and Pakistan, and also between China and India in the northeastern portion of the region. The conflict started after the partition of India in 1947 as both India and Pakistan claimed the entirety of the former princely state of Jammu and Kashmir.', 1947, NULL, NULL, NULL, NULL, NULL, 'year', '1947', 78, 'https://en.wikipedia.org/wiki/Kashmir_conflict'),
  ('Q738854', '1950 Assam–Tibet earthquake', 'The 1950 Assam–Tibet earthquake, also known as the Assam earthquake, occurred on 15 August and had a moment magnitude of 8.7. The epicentre was located in the Mishmi Hills.', 1950, 8, 15, NULL, NULL, NULL, 'day', '15 August 1950', 57, 'https://en.wikipedia.org/wiki/1950_Assam%E2%80%93Tibet_earthquake'),
  ('Q208694', 'Sino-Indian War', 'The Sino-Indian War, also known as the China–India War or the Indo-China War, was an armed conflict between China and India that took place from October to November 1962. It was a military escalation of the Sino-Indian border dispute.', 1962, 10, 20, 1962, 11, 21, 'day', '20 October 1962 – 21 November 1962', 76, 'https://en.wikipedia.org/wiki/Sino-Indian_War'),
  ('Q233583', 'Indo-Pakistani War of 1965', 'The India–Pakistan war of 1965, also known as the second Kashmir war, was an armed conflict between Pakistan and India that took place from August 1965 to September 1965. The conflict began following Pakistan''s unsuccessful Operation Gibraltar, which was designed to infiltrate forces into Jammu and Kashmir to precipitate an insurgency against Indian rule.', 1965, 8, NULL, 1965, 9, 23, 'month', 'August 1965 – 23 September 1965', 78, 'https://en.wikipedia.org/wiki/India%E2%80%93Pakistan_war_of_1965'),
  ('Q979845', 'Naxalite–Maoist insurgency', 'The Naxalite–Maoist insurgency is an ongoing conflict between the Government of India and communist groups. The Naxalites are a group of communist organisations following Maoist political sentiment and ideology, and claim to be fighting for rural poor and wage a people''s war against the government.', 1967, 5, 18, NULL, NULL, NULL, 'day', '18 May 1967', 64, 'https://en.wikipedia.org/wiki/Naxalite%E2%80%93Maoist_insurgency'),
  ('Q2726232', 'Emergency', 'The Emergency in India was a 21 month period from 1975 to 1977 when prime minister Indira Gandhi declared a state of emergency across India by citing internal and external threats to the country. Officially issued by president Fakhruddin Ali Ahmed under Article 352 of the Constitution of India because of a prevailing "Internal Disturbance", the Emergency were in effect from 25 June 1975 and ended on 21 March 1977.', 1975, 6, 25, 1977, 3, 21, 'day', '25 June 1975 – 21 March 1977', 65, 'https://en.wikipedia.org/wiki/The_Emergency_(India)'),
  ('Q3098353', 'Air India Flight 855', 'Air India Flight 855 was a scheduled passenger flight from Bombay (now Mumbai), India, to Dubai, United Arab Emirates. On 1 January 1978, the Boeing 747 operating the flight crashed into the Arabian Sea about 3 km (1.9 mi; 1.6 nmi) off the coast of Bandra, less than two minutes after take-off, killing all 213 passengers and crew on board.', 1978, 1, 1, NULL, NULL, NULL, 'day', '1 January 1978', 59, 'https://en.wikipedia.org/wiki/Air_India_Flight_855'),
  ('Q3504310', '1984 anti-Sikh riots', 'The 1984 anti-Sikh riots, also known as the 1984 Sikh massacre, were a series of organised pogroms against Sikhs in India following the assassination of Indira Gandhi by her Sikh bodyguards. Government estimates were that about 2,800 Sikhs were killed in Delhi and 3,350 nationwide, whilst other sources estimate the number of deaths at about 8,000–17,000.', 1984, 11, 3, 1984, 11, 3, 'day', '3 November 1984', 63, 'https://en.wikipedia.org/wiki/1984_anti-Sikh_riots'),
  ('Q6019809', 'Indian Airlines Flight 605', 'Indian Airlines Flight 605 was a scheduled domestic passenger flight from Bombay to Bangalore. On 14 February 1990, an Airbus A320 registered as VT-EPN, crashed onto a golf course while attempting to land at Bangalore, killing 92 of 146 people on board.', 1990, 2, 14, NULL, NULL, NULL, 'day', '14 February 1990', 55, 'https://en.wikipedia.org/wiki/Indian_Airlines_Flight_605'),
  ('Q3423445', 'assassination of Rajiv Gandhi', 'Former Indian prime minister Rajiv Gandhi was assassinated by a suicide bombing in Sriperumbudur in Tamil Nadu on 21 May 1991. The incident resulted in the deaths of 17 people including Rajiv Gandhi and the perpetrator, 22-year-old Kalaivani Rajaratnam, a member of the Tamil militant organization Liberation Tigers of Tamil Eelam (LTTE).', 1991, 5, 21, NULL, NULL, NULL, 'day', '21 May 1991', 60, 'https://en.wikipedia.org/wiki/Assassination_of_Rajiv_Gandhi'),
  ('Q657494', 'Demolition of the Babri Masjid', 'The Babri Masjid, a 16th-century mosque in the Indian city of Ayodhya, was destroyed on 6 December 1992 by a large group of activists of the Vishva Hindu Parishad and allied organisations. The mosque had been the subject of a lengthy socio-political dispute, and was targeted after a political rally organised by Hindu nationalist organisations turned violent.', 1992, 12, 6, NULL, NULL, NULL, 'day', '6 December 1992', 53, 'https://en.wikipedia.org/wiki/Demolition_of_the_Babri_Masjid'),
  ('Q118373', 'Charkhi Dadri mid-air collision', 'On 12 November 1996, Saudia Flight 763, a Boeing 747-100B en route from Delhi, India to Jeddah with a stopover in Dhahran, Saudi Arabia, and Kazakhstan Airlines Flight 1907, an Ilyushin Il-76 en route from Shymkent, Kazakhstan to Delhi, collided over the city of Charkhi Dadri in the state of Haryana, around 100 kilometres (62 mi; 54 nmi) west of Delhi. The crash killed all 349 people on board both planes, making it the world''s deadliest mid-air collision, the deadliest aviation accident without survivors, and the deadliest aviation accident in the Indian subcontinent.', 1996, 11, 12, NULL, NULL, NULL, 'day', '12 November 1996', 66, 'https://en.wikipedia.org/wiki/1996_Charkhi_Dadri_mid-air_collision'),
  ('Q404517', 'Kargil War', 'The Kargil War, also known as the Kargil conflict, was fought between India and Pakistan from May to July 1999 in the Kargil district of Ladakh, then part of the Indian-administered state of Jammu and Kashmir and along the Line of Control (LoC). In India, the conflict is also referred to as Operation Vijay (lit. ''Victory''), which was the codename of the Indian military operation in the region.', 1999, NULL, NULL, 1999, 7, 26, 'year', '1999', 76, 'https://en.wikipedia.org/wiki/Kargil_War'),
  ('Q2441400', '2001 Gujarat earthquake', 'An earthquake struck India and Pakistan on 26 January 2001 at 08:46 am IST. The epicentre was about 9 km south-southwest of the village of Chobari in Bhachau Taluka of Kutch district in Gujarat, India. The earthquake had a maximum Mercalli intensity of XII (Extreme).', 2001, 1, 26, NULL, NULL, NULL, 'day', '26 January 2001', 64, 'https://en.wikipedia.org/wiki/2001_Gujarat_earthquake'),
  ('Q3351820', '2001 Indian Parliament attack', 'The 2001 Indian Parliament attack was a terrorist attack on the Parliament of India in New Delhi, India, on 13 December 2001. The attack was carried out by five Jaish-e-Mohammed militants and resulted in the deaths of six Delhi Police personnel, two Parliament Security Service personnel, and a gardener.', 2001, 12, 13, NULL, NULL, NULL, 'day', '13 December 2001', 56, 'https://en.wikipedia.org/wiki/2001_Indian_Parliament_attack'),
  ('Q1747156', '2002 Gujarat violence', 'On 28 February 2002, a three-day period of inter-communal violence began in the western Indian state of Gujarat. The burning of a train in Godhra the day before, which caused the deaths of 58 Hindu pilgrims and karsevaks (religious volunteers) returning from Ayodhya, is cited as having instigated the violence.', 2002, NULL, NULL, NULL, NULL, NULL, 'year', '2002', 63, 'https://en.wikipedia.org/wiki/2002_Gujarat_violence'),
  ('Q130754', '2004 Indian Ocean earthquake', 'On 26 December 2004, at 07:58:53 local time (UTC+7), a Mw 9.2–9.3 earthquake struck with its epicenter off the west coast of Aceh, in northern Sumatra, Indonesia. The undersea megathrust earthquake, known in the scientific community as the Sumatra–Andaman earthquake, was caused by a rupture along the fault boundary between the Burma plate and the Indian plate, and reached a maximum Mercalli intensity of IX in some areas.', 2004, 12, 26, NULL, NULL, NULL, 'day', '26 December 2004', 85, 'https://en.wikipedia.org/wiki/2004_Indian_Ocean_earthquake_and_tsunami'),
  ('Q210137', '2005 Kashmir earthquake', 'On 8 October 2005, at 08:50:39 PKT, a Mw 7.6 earthquake struck the Azad Kashmir region in northern Pakistan. Its epicenter was located in the tehsil of Patikka, near the city of Muzaffarabad.', 2005, 10, 8, NULL, NULL, NULL, 'day', '8 October 2005', 75, 'https://en.wikipedia.org/wiki/2005_Kashmir_earthquake'),
  ('Q571891', '2011 Sikkim earthquake', 'The 2011 Sikkim earthquake (also known as the 2011 Himalayan earthquake) occurred with a moment magnitude of 6.9 and was centered within the Kanchenjunga Conservation Area, near the border of Nepal and the Indian state of Sikkim, at 18:10 IST on Sunday, 18 September. The earthquake was felt across northeastern India, Nepal, Bhutan, Bangladesh, and southern Tibet.', 2011, 9, 18, NULL, NULL, NULL, 'day', '18 September 2011', 55, 'https://en.wikipedia.org/wiki/2011_Sikkim_earthquake'),
  ('Q383991', '2012 Indian Ocean earthquakes', 'The 2012 Indian Ocean earthquakes were magnitude 8.6 and 8.2 Mw undersea earthquakes that struck near the Indonesian province of Aceh on 11 April at 15:38 local time. Initially, authorities feared that the initial earthquake would cause a tsunami and warnings were issued across the Indian Ocean; however, these warnings were subsequently cancelled.', 2012, 4, 11, NULL, NULL, NULL, 'day', '11 April 2012', 66, 'https://en.wikipedia.org/wiki/2012_Indian_Ocean_earthquakes'),
  ('Q13507070', '2013 North India floods', 'In June 2013, a mid-day cloudburst centered on the North Indian state of Uttarakhand caused devastating floods and landslides, becoming the country''s worst natural disaster since the 2004 tsunami. The rainfall received that month was far greater than the rainfall the state usually received.', 2013, 6, NULL, NULL, NULL, NULL, 'month', 'June 2013', 53, 'https://en.wikipedia.org/wiki/2013_North_India_floods'),
  ('Q19830062', 'April 2015 Nepal earthquake', 'The April 2015 Nepal earthquake (also known as the Gorkha earthquake) killed 8,962 people and injured 21,952 across the countries of Nepal, India, China and Bangladesh. It occurred at 11:56 Nepal Standard Time on Saturday 25 April 2015, with a magnitude of Mw 7.8–7.9 or Ms 8.1 and a maximum Mercalli Intensity of X (Extreme).', 2015, 4, 25, NULL, NULL, NULL, 'day', '25 April 2015', 82, 'https://en.wikipedia.org/wiki/April_2015_Nepal_earthquake'),
  ('Q21528743', 'November 2015 South Indian floods', 'The 2015 South India floods resulted from heavy rainfall generated by the annual northeast monsoon in November–December 2015. They affected the Coromandel Coast region of the South Indian states of Tamil Nadu and Andhra Pradesh.', 2015, 11, 8, NULL, NULL, NULL, 'day', '8 November 2015', 53, 'https://en.wikipedia.org/wiki/2015_South_India_floods'),
  ('Q23772755', 'Kollam temple fire', 'On 10 April 2016 at approximately 03:30 am IST, the Puttingal Temple in Paravur, Kollam, Kerala, India, experienced a fireworks accident after firework celebrations went awry. As a result, 111 people were killed and more than 350 were injured, including some with severe burns.', 2016, 4, 10, NULL, NULL, NULL, 'day', '10 April 2016', 61, 'https://en.wikipedia.org/wiki/Puttingal_temple_fire'),
  ('Q56044878', '2018 Kerala floods', 'On 16 August 2018, severe floods affected the south Indian state Kerala, due to unusually heavy rainfall during the monsoon season. It was the worst flood in Kerala in nearly a century since the great flood of ''99 that took place in 1924.', 2018, 8, 30, 2018, 8, NULL, 'day', '30 August 2018 – August 2018', 57, 'https://en.wikipedia.org/wiki/2018_Kerala_floods'),
  ('Q61732241', '2019 Pulwama attack', 'The 2019 Pulwama attack occurred on 14 February 2019, when a convoy of vehicles carrying Indian security personnel on the Jammu–Srinagar National Highway was attacked by a vehicle-borne suicide bomber at Lethapora in the Pulwama district of the erstwhile state of Jammu and Kashmir. The attack killed 40 Central Reserve Police Force (CRPF) personnel as well as the perpetrator — Adil Ahmad Dar— who was a local Kashmiri youth from the Pulwama district.', 2019, 2, 14, NULL, NULL, NULL, 'day', '14 February 2019', 65, 'https://en.wikipedia.org/wiki/2019_Pulwama_attack'),
  ('Q61896704', '2019 India–Pakistan border skirmishes', 'In the aftermath of the Pulwama attack on 14 February 2019, a standoff emerged between India and Pakistan consisting of cross-border airstrikes and exchanges of gunfire between India and Pakistan across the de facto border in the disputed Kashmir region, which is subject to extensive territorial claims by both countries. The Pulwama attack in Jammu and Kashmir had killed 40 Indian Central Reserve Police Force personnel.', 2019, 2, 14, NULL, NULL, NULL, 'day', '14 February 2019', 63, 'https://en.wikipedia.org/wiki/2019_India%E2%80%93Pakistan_border_skirmishes'),
  ('Q78455589', 'Citizenship (Amendment) Act protests', 'Protests occurred after the Citizenship Amendment Act (CAA) was enacted by the Government of India on 12 December 2019. The move sparked widespread national and overseas ongoing protests against the act and its associated proposals of the National Register of Citizens (NRC).', 2019, 12, 4, 2020, 3, 14, 'day', '4 December 2019 – 14 March 2020', 58, 'https://en.wikipedia.org/wiki/Citizenship_Amendment_Act_protests'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86347874', '2020 Delhi riots', 'The 2020 Delhi riots, or North East Delhi riots, were multiple waves of bloodshed, property destruction, and rioting in North East Delhi, India, beginning on 23 February 2020 and brought about chiefly by Hindu mobs attacking Muslims. Of the 53 people killed, two-thirds were Muslims who were shot, slashed with repeated blows, or set on fire.', 2020, NULL, NULL, NULL, NULL, NULL, 'year', '2020', 57, 'https://en.wikipedia.org/wiki/2020_Delhi_riots'),
  ('Q93468280', 'Visakhapatnam gas leak', 'The Visakhapatnam gas leak, also referred to as the Vizag gas leak, was an industrial accident involving a styrene gas leak that occurred at the LG Polymers chemical plant in the R. R. Venkatapuram village of the Gopalapatnam neighbourhood, located at the outskirts of Visakhapatnam, Andhra Pradesh, India, during the early morning of 7 May 2020. The resulting vapour cloud spread over a radius of around 3.0 km (1.9 mi), affecting the nearby areas and villages.', 2020, 5, 7, NULL, NULL, NULL, 'day', '7 May 2020', 61, 'https://en.wikipedia.org/wiki/Visakhapatnam_gas_leak'),
  ('Q102439127', '2020–2021 Indian farmers'' protest', 'The 2020–2021 Indian farmers'' protest was a protest against three farm acts passed by the Parliament of India in September 2020. The acts, often called the Farm Bills, had been described as "anti-farmer laws" by many farmer unions, and politicians from the opposition who said that the three laws would leave farmers at the "mercy of corporates" since the farmer-trader disputes were taken to SDM instead of judiciary.', 2020, 8, 9, 2021, 12, 11, 'day', '9 August 2020 – 11 December 2021', 68, 'https://en.wikipedia.org/wiki/2020%E2%80%932021_Indian_farmers''_protest'),
  ('Q105358710', '2021 Uttarakhand glacial outburst flood', 'The 2021 Uttarakhand flood, also known as the Chamoli disaster, began on 7 February 2021 in the environs of the Nanda Devi National Park, a UNESCO World Heritage Site in the outer Garhwal Himalayas in Uttarakhand state, India. It was caused by a large rock and ice avalanche consisting of material dislodged from Ronti peak.', 2021, 2, 7, NULL, NULL, NULL, 'day', '7 February 2021', 59, 'https://en.wikipedia.org/wiki/2021_Uttarakhand_flood'),
  ('Q107695056', '2021 Maharashtra floods', 'A series of floods took place across the Indian State of Maharashtra in 2021. As of 28 July 2021, around 251 people have died and over 100 are still missing due to floods and landslides.', 2021, 7, 22, NULL, NULL, NULL, 'day', '22 July 2021', 59, 'https://en.wikipedia.org/wiki/2021_Maharashtra_floods'),
  ('Q128098219', '2024 Wayanad landslide', 'A series of landslides occurred in Punjirimattom, Mundakkai, Chooralmala, and Vellarimala villages in Meppadi panchayat, Vythiri taluk in Wayanad district, Kerala, India in the early hours of 30 July 2024. The landslides were caused by heavy rains that caused hillsides to collapse onto the areas below.', 2024, 7, 30, NULL, NULL, NULL, 'day', '30 July 2024', 65, 'https://en.wikipedia.org/wiki/2024_Wayanad_landslides'),
  ('Q134044277', '2025 Pahalgam attack', 'The 2025 Pahalgam attack, also referred to as the 2025 Pahalgam massacre, was an Islamist terrorist attack on tourists by three armed militants near Pahalgam in Indian-administered Jammu and Kashmir in which 26 civilians were killed on 22 April 2025. The attackers targeted Hindu tourists, though a Christian tourist and a local Muslim pony ride operator were also killed.', 2025, 4, 22, NULL, NULL, NULL, 'day', '22 April 2025', 72, 'https://en.wikipedia.org/wiki/2025_Pahalgam_attack'),
  ('Q134880537', 'Air India Flight 171', 'Air India Flight 171 was a scheduled international passenger flight from Ahmedabad Airport, Gujarat, India, to London Gatwick Airport in Crawley, West Sussex, England. On 12 June 2025, at 13:39 IST (08:09 UTC), the Boeing 787 Dreamliner operating the flight crashed 32 seconds after takeoff into the student hostels of the Byramjee Jeejeebhoy Medical College, 1.7 kilometres (1 mi; 0.9 nmi) from the runway.', 2025, 6, 12, NULL, NULL, NULL, 'day', '12 June 2025', 79, 'https://en.wikipedia.org/wiki/Air_India_Flight_171'),
  ('Q136758468', '2025 Delhi car explosion', 'On 10 November 2025, a car exploded near the Red Fort in Delhi, India, killing at least 15 people and injuring more than 20 others. According to the Delhi Police, there were two to three people inside the car at the time of the explosion.', 2025, 11, 10, NULL, NULL, NULL, 'day', '10 November 2025', 59, 'https://en.wikipedia.org/wiki/2025_Delhi_Red_Fort_blast'),
  ('Q140615137', '2026 Delhi Jantar Mantar protests', 'A series of demonstrations took place in Jantar Mantar, New Delhi, India, between 6 June and 25 July 2026. They were initiated by the Cockroach Janta Party (CJP), an Indian youth-based satirical political movement, along with left-wing student organisations including the All India Students Federation, All India Students Association, and Students'' Federation of India.', 2026, NULL, NULL, 2026, 7, 25, 'year', '2026', 56, 'https://en.wikipedia.org/wiki/2026_Delhi_Jantar_Mantar_protests');
